import os, re, glob, collections

EXCLUDE_DIRS = {'.obsidian', '.trash', '.git', '.shale'}

def should_skip(path):
    parts = path.split(os.sep)
    return any(p in EXCLUDE_DIRS for p in parts)

files = []
for root, dirs, filenames in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS]
    for fn in filenames:
        if fn.endswith('.md'):
            files.append(os.path.join(root, fn))

link_re = re.compile(r'\[\[([^\]|#]+)')

title_to_path = {}
aliases_map = collections.defaultdict(list)
outlinks = {}

for path in files:
    title = os.path.splitext(os.path.basename(path))[0]
    title_to_path[title.lower()] = path
    try:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
    except Exception:
        content = ''
    links = set(m.strip().lower() for m in link_re.findall(content))
    outlinks[path] = links
    # aliases from frontmatter
    m = re.search(r'^aliases:\s*\[(.*?)\]', content, re.MULTILINE)
    if m:
        for a in m.group(1).split(','):
            a = a.strip().strip('"').strip("'")
            if a:
                aliases_map[a.lower()].append(path)

alias_to_path = {}
for a, paths in aliases_map.items():
    if len(paths) == 1:
        alias_to_path[a] = paths[0]

indegree = collections.Counter()
for path, links in outlinks.items():
    for l in links:
        target_path = title_to_path.get(l) or alias_to_path.get(l)
        if target_path and target_path != path:
            indegree[target_path] += 1

results = []
for path in files:
    out_count = len(outlinks[path])
    in_count = indegree[path]
    if out_count == 0 and in_count == 0:
        results.append(path)

results.sort()
print(f"Total files scanned: {len(files)}")
print(f"True orphans (0 outlinks, 0 backlinks): {len(results)}")
print()
for r in results:
    print(r)
